// This code:
// - Reads the AI Agent / Gemini output
// - Parses the JSON (even if wrapped in text/markdown)
// - Merges with raw webhook data from Lead Webhook1
// - Outputs: { name, email, phone, model, datetime, intent_score }

const out = [];
const items = $input.all();

function safeParse(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  let txt = String(raw).trim();

  // Strip ```json fences if present
  txt = txt
    .replace(/^```json/i, '')
    .replace(/^```/, '')
    .replace(/```$/, '')
    .trim();

  // First try direct JSON
  try {
    return JSON.parse(txt);
  } catch (e) {}

  // If that fails, try to extract the first { ... } block
  const match = txt.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      return JSON.parse(match[0]);
    } catch (e2) {}
  }

  return {};
}

items.forEach((item) => {
  const geminiJson = item.json || {};

  // 1) Get content from AI Agent output
  let content =
    geminiJson.text ??
    geminiJson.output ??
    geminiJson.result ??
    geminiJson.response ??
    geminiJson;

  const parsed = safeParse(content);

  // 2) Get original webhook payload (single-item use case)
  const webhook = $node["Lead Webhook1"].json;
  const body = webhook.body || webhook;

  // 3) Compute intent_score safely
  let score =
    parsed.intent_score ??
    parsed.intentScore ??
    parsed.intent ??
    null;

  if (score == null) {
    // Fallback if model didn't return any score
    score = 0.5;
  } else {
    score = Number(score);
    if (Number.isNaN(score)) score = 0.5;
    if (score < 0) score = 0;
    if (score > 1) score = 1;
  }

  // 4) Build final lead object
  const lead = {
    name: parsed.name ?? body.name ?? null,
    email: body.email ?? null,
    phone: parsed.phone ?? body.phone ?? null,
    model: parsed.model ?? body.model ?? body.carModel ?? null,
    datetime: parsed.datetime ?? body.datetime ?? body.dateTime ?? null,
    intent_score: score,
  };

  out.push({ json: lead });
});

return out;
